    perms = sa.table("permissions", sa.column("id", sa.Uuid), sa.column("role_id", sa.Uuid), sa.column("permission", sa.String))
    role_rows, perm_rows = [], []
    for key, (name, description) in _ROLES.items():
        role_id = uuid.uuid5(_NS, f"role:{key}")
        role_rows.append({"id": role_id, "org_id": None, "key": key, "name": name, "description": description, "created_at": now, "updated_at": now})
        perm_rows += [{"id": uuid.uuid5(_NS, f"perm:{key}:{p}"), "role_id": role_id, "permission": p} for p in _PERMISSIONS[key]]
